50| <body>
51| <div id="wrap">
52|   <canvas id="game"></canvas>
53| </div>
54| <button id="clearBtn">Clear</button>
55| <script>
56|   const CARTRIDGE = {
57|     send(type, payload = {}) {
58|       window.parent.postMessage(
59|         { source: "cartridge", v: 1, type, payload },
60|         "*",
61|       );
62|     },
63|   };
64| </script>
65| <script>
66| (function() {
67|   const canvas = document.getElementById("game");
68|   const ctx = canvas.getContext("2d");
69|   const clearBtn = document.getElementById("clearBtn");
70| 
71|   let dpr = Math.max(1, window.devicePixelRatio || 1);
72|   let W = 0, H = 0;
73| 
74|   function resize() {
75|     W = window.innerWidth;
76|     H = window.innerHeight;
77|     dpr = Math.max(1, window.devicePixelRatio || 1);
78|     canvas.width = Math.floor(W * dpr);
79|     canvas.height = Math.floor(H * dpr);
80|     canvas.style.width = W + "px";
81|     canvas.style.height = H + "px";
82|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
83|     draw();
84|   }
85|   window.addEventListener("resize", resize);
86| 
87|   // ---- palette ----
88|   const COL_BG = "#f4ecd8";
89|   const COL_LAYER = "#e07a5f";
90|   const COL_ACCENT = "#3d405b";
91|   const COL_HILITE = "#81b29a";
92| 
93|   // seeded jitter helper
94|   function mulberry32(seed) {
95|     return function() {
96|       seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
97|       let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
98|       t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
99|       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
100|     };
101|   }
102| 
103|   const STICKER_TYPES = ["leaf", "shell", "star"];
104| 
105|   const pieces = [];
106|   let tally = 0;
107|   let paused = false;
108|   let running = false;
109|   let nextTypeIndex = 0;
110|   let seedCounter = 1;
111| 
112|   let t = 0; // animation time
113| 
114|   function place(x, y) {
115|     const type = STICKER_TYPES[nextTypeIndex % STICKER_TYPES.length];
116|     nextTypeIndex++;
117|     const rnd = mulberry32(seedCounter++ * 7919 + Math.floor(x * 13 + y * 7));
118|     const scale = 0.85 + rnd() * 0.4;
119|     const rot = (rnd() - 0.5) * 0.6;
120|     const hue = rnd();
121|     const wobblePhase = rnd() * Math.PI * 2;
122|     const wobbleSpeed = 1.2 + rnd() * 0.8;
123|     pieces.push({
124|       x, y, type, scale, rot, hue,
125|       wobblePhase, wobbleSpeed,
126|       born: t
127|     });
128|     tally += 1;
129|     CARTRIDGE.send("score", { value: tally });
130|   }
131| 
132|   // Single clear-the-table function: used by the host reset command
133|   // AND by the visible in-game Clear button. Nothing else resets state.
134|   function clearTable() {
135|     pieces.length = 0;
136|     tally = 0;
137|     nextTypeIndex = 0;
138|     CARTRIDGE.send("score", { value: 0 });
139|     draw();
140|   }
141| 
142|   function jitterPoint(rnd, x, y, amt) {
143|     return [x + (rnd() - 0.5) * amt, y + (rnd() - 0.5) * amt];
144|   }
145| 
146|   function drawShadowPath(pathFn) {
147|     ctx.save();
148|     ctx.shadowColor = "rgba(61,64,91,0.35)";
149|     ctx.shadowBlur = 6;
150|     ctx.shadowOffsetX = 2;
151|     ctx.shadowOffsetY = 3;
152|     pathFn();
153|     ctx.restore();
154|   }
155| 
156|   function drawLeaf(rnd, size, colorMain) {
157|     const pts = [];
158|     const n = 10;
159|     for (let i = 0; i <= n; i++) {
160|       const a = (i / n) * Math.PI * 2;
161|       const rx = size * (0.55 + 0.45 * Math.abs(Math.cos(a)));
162|       const ry = size * 0.85;
163|       let px = Math.cos(a) * rx * 0.5;
164|       let py = Math.sin(a) * ry * 0.5;
165|       const [jx, jy] = jitterPoint(rnd, px, py, 1.5);
166|       pts.push([jx, jy]);
167|     }
168|     const build = () => {
169|       ctx.beginPath();
170|       ctx.moveTo(pts[0][0], pts[0][1]);
171|       for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
172|       ctx.closePath();
173|     };
174|     drawShadowPath(() => {
175|       ctx.fillStyle = colorMain;
176|       build();
177|       ctx.fill();
178|     });
179|     build();
180|     ctx.fillStyle = colorMain;
181|     ctx.fill();
182|     ctx.strokeStyle = COL_ACCENT;
183|     ctx.lineWidth = 1.4;
184|     ctx.beginPath();
185|     ctx.moveTo(0, -size * 0.4);
186|     ctx.lineTo(0, size * 0.4);
187|     ctx.stroke();
188|   }
189| 
190|   function drawShell(rnd, size, colorMain) {
191|     const n = 12;
192|     const build = () => {
193|       ctx.beginPath();
194|       for (let i = 0; i <= n; i++) {
195|         const a = Math.PI + (i / n) * Math.PI;
196|         let px = Math.cos(a) * size * 0.6;
197|         let py = Math.sin(a) * size * 0.55 + size * 0.15;
198|         const [jx, jy] = jitterPoint(rnd, px, py, 1.5);
199|         if (i === 0) ctx.moveTo(jx, jy); else ctx.lineTo(jx, jy);
200|       }
201|       ctx.lineTo(size * 0.05, size * 0.6);
202|       ctx.closePath();
203|     };
204|     drawShadowPath(() => {
205|       ctx.fillStyle = colorMain;
206|       build();
207|       ctx.fill();
208|     });
209|     build();
210|     ctx.fillStyle = colorMain;
211|     ctx.fill();
212|     ctx.strokeStyle = COL_ACCENT;
213|     ctx.lineWidth = 1.2;
214|     for (let i = 1; i < 5; i++) {
215|       const a = Math.PI + (i / 5) * Math.PI;
216|       ctx.beginPath();
217|       ctx.moveTo(0, size * 0.1);
218|       ctx.lineTo(Math.cos(a) * size * 0.6, Math.sin(a) * size * 0.55 + size * 0.15);
219|       ctx.stroke();
220|     }
221|   }
222| 
223|   function drawStar(rnd, size, colorMain) {
224|     const spikes = 5;
225|     const outerR = size * 0.65;
226|     const innerR = size * 0.28;
227|     const build = () => {
228|       ctx.beginPath();
229|       for (let i = 0; i < spikes * 2; i++) {
230|         const a = (Math.PI / spikes) * i - Math.PI / 2;
231|         const r = i % 2 === 0 ? outerR : innerR;
232|         let px = Math.cos(a) * r;
233|         let py = Math.sin(a) * r;
234|         const [jx, jy] = jitterPoint(rnd, px, py, 1.4);
235|         if (i === 0) ctx.moveTo(jx, jy); else ctx.lineTo(jx, jy);
236|       }
237|       ctx.closePath();
238|     };
239|     drawShadowPath(() => {
240|       ctx.fillStyle = colorMain;
241|       build();
242|       ctx.fill();
243|     });
244|     build();
245|     ctx.fillStyle = colorMain;
246|     ctx.fill();
247|   }
248| 
249|   function drawPiece(p) {
250|     const wobble = Math.sin(t * p.wobbleSpeed + p.wobblePhase) * 0.08;
251|     ctx.save();
252|     ctx.translate(p.x, p.y);
253|     ctx.rotate(p.rot + wobble);
254|     ctx.scale(p.scale, p.scale);
255|     const rnd = mulberry32(Math.floor(p.x * 31 + p.y * 17 + 1));
256|     const size = 46;
257|     let col = COL_LAYER;
258|     if (p.type === "leaf") col = COL_HILITE;
259|     else if (p.type === "shell") col = COL_LAYER;
260|     else col = "#e0a15f";
261|     if (p.type === "leaf") drawLeaf(rnd, size, col);
262|     else if (p.type === "shell") drawShell(rnd, size, col);
263|     else drawStar(rnd, size, col);
264|     ctx.restore();
265|   }
266| 
267|   function drawBackgroundCard() {
268|     ctx.fillStyle = COL_BG;
269|     ctx.fillRect(0, 0, W, H);
270|     const rnd = mulberry32(99);
271|     const margin = 10;
272|     const pts = [
273|       [margin, margin], [W - margin, margin],
274|       [W - margin, H - margin], [margin, H - margin]
275|     ];
276|     ctx.save();
277|     ctx.shadowColor = "rgba(61,64,91,0.25)";
278|     ctx.shadowBlur = 8;
279|     ctx.shadowOffsetY = 4;
280|     ctx.fillStyle = "#efe3c8";
281|     ctx.beginPath();
282|     pts.forEach((p, i) => {
283|       const [jx, jy] = jitterPoint(rnd, p[0], p[1], 2);
284|       if (i === 0) ctx.moveTo(jx, jy); else ctx.lineTo(jx, jy);
285|     });
286|     ctx.closePath();
287|     ctx.fill();
288|     ctx.restore();
289|   }
290| 
291|   function roundRect(x, y, w, h, r) {
292|     ctx.beginPath();
293|     ctx.moveTo(x + r, y);
294|     ctx.arcTo(x + w, y, x + w, y + h, r);
295|     ctx.arcTo(x + w, y + h, x, y + h, r);
296|     ctx.arcTo(x, y + h, x, y, r);
297|     ctx.arcTo(x, y, x + w, y, r);
298|     ctx.closePath();
299|   }
300| 
301|   function drawHUD() {
302|     const plateW = 150, plateH = 56;
303|     const x = 12, y = 12;
304|     ctx.save();
305|     ctx.shadowColor = "rgba(61,64,91,0.3)";
306|     ctx.shadowBlur = 6;
307|     ctx.shadowOffsetY = 3;
308|     ctx.fillStyle = COL_ACCENT;
309|     roundRect(x, y, plateW, plateH, 12);
310|     ctx.fill();
311|     ctx.restore();
312| 
313|     ctx.fillStyle = COL_BG;
314|     ctx.font = "bold 18px sans-serif";
315|     ctx.textBaseline = "middle";
316|     ctx.textAlign = "left";
317|     ctx.fillText("Stickers: " + tally, x + 14, y + plateH / 2 + 1);
318|   }
319| 
320|   function drawHint() {
321|     if (running) return;
322|     const pulse = 0.6 + 0.4 * Math.sin(t * 3);
323|     ctx.save();
324|     ctx.globalAlpha = pulse;
325|     ctx.fillStyle = COL_ACCENT;
326|     ctx.font = "bold 26px sans-serif";
327|     ctx.textAlign = "center";
328|     ctx.textBaseline = "middle";
329|     ctx.fillText("Tap to begin", W / 2, H / 2);
330|     ctx.restore();
331|   }
332| 
333|   function draw() {
334|     drawBackgroundCard();
335|     for (const p of pieces) drawPiece(p);
336|     drawHUD();
337|     drawHint();
338|   }
339| 
340|   function frame() {
341|     if (!paused) {
342|       t += 1 / 60;
343|     }
344|     draw();
345|     requestAnimationFrame(frame);
346|   }
347| 
348|   canvas.style.touchAction = "none";
349|   canvas.addEventListener("pointerdown", (event) => {
350|     event.preventDefault();
351|     if (paused) return;
352|     if (!running) {
353|       running = true;
354|       CARTRIDGE.send("start");
355|       return;
356|     }
357|     const rect = canvas.getBoundingClientRect();
358|     const x = event.clientX - rect.left;
359|     const y = event.clientY - rect.top;
360|     place(x, y);
361|   });
362| 
363|   clearBtn.addEventListener("click", clearTable);
364| 
365|   window.addEventListener("message", (event) => {
366|     const data = event.data;
367|     if (!data || data.source !== "cartridge-host") return;
368|     if (data.type === "pause") paused = true;
369|     if (data.type === "resume") paused = false;
370|     if (data.type === "reset") clearTable();
371|   });
372| 
373|   resize();
374|   CARTRIDGE.send("boot", { title: "Sticker Table", gameType: "toy-box", lang: "en" });
375|   CARTRIDGE.send("start");
376|   requestAnimationFrame(frame);
377| })();
378| </script>
379| </body>
380| </html>
